namespace OpenScctEditor.Shell;

public static partial class TutorialCatalog
{
    public static string? DoorTutorialForPrefab(string name) => name switch
    {
        "swing_door" or "glazed_door" => "door-hinged",
        "sliding_door" => "door-sliding",
        "roller_door" => "door-rising",
        "double_hinged_door" => "door-double-hinged",
        "double_sliding_door" => "door-double-sliding",
        "hackable_door" => "door-hacking",
        "automatic_door" => "door-automatic",
        "door_switch" => "door-switch",
        _ => null,
    };

    private static IEnumerable<EditorTutorial> DoorLessons() =>
    [
        new("door-hinged", "Build a hinged door", "door swing left right jamb panelled plain industrial glazed glass louvred security single", [
            S("Choose a finish", "In Doors choose Plain, Panelled, Industrial, Glazed, Louvred or Security. Style controls appearance; Movement controls how the leaf opens. A glazed door is a moving door with a window, not the separate breakable Windows tool.", "panel:Doors"),
            S("Choose the hinge", "Set Movement to Swing Left or Swing Right. Open angle sets the swing in degrees; Reverse opening changes its direction. Set Width and Height for the clear doorway and leave enough room for the entire leaf to swing.", "panel:Doors|Movement"),
            S("Place at floor level", "Click Place Door and point at the bottom of an editable wall. The preview shows the opening and the swung leaf. R flips its facing on a wall. Click to place; Escape cancels. For a retained baked wall, use an existing opening or recover its brushes first.", "panel:Doors|Place Door"),
            S("Inspect and resize", "Select the placed door. Inspector's Door section changes its dimensions, style and opening. Show open previews the swing with the frame fixed; Show closed ends the preview. Use Scale for Width and Height handles. Height edits keep the bottom on the floor.", "panel:Inspector"),
            S("Test the full swing", "Check, Build and Play. With Contact · timed activation, approach from each side and wait for it to close. Check the hinge, opening direction, nearby walls and player clearance. Save the editable .osmap project.", "action:build.check")]),
        new("door-sliding", "Build a sliding door", "door slide left right horizontal travel reverse single", [
            S("Choose horizontal movement", "Choose a style in Doors and set Movement to Slide Left or Slide Right. All six styles can slide. Width and Height describe the clear opening; the frame stays in place as the leaf moves sideways.", "panel:Doors|Movement"),
            S("Reserve the sliding space", "Travel 0 automatically clears the opening and frame. Set an explicit Travel only when you need a different distance. Reverse opening swaps the direction. Leave a clear pocket beside the doorway for the complete leaf and its thickness.", "panel:Doors|Travel"),
            S("Place and preview", "Use Place Door at the bottom of an editable wall to create its cut. R flips facing on the wall. Click to place, select the door, then use Show open in Inspector to check that the leaf clears the opening without passing through adjacent rooms.", "panel:Doors|Place Door"),
            S("Set the timing", "In Inspector set Open time for the seconds spent moving and Stay open for the pause before a timed door closes. Contact · timed works on player contact; trigger modes need an event connection. Show closed ends the pose preview before further editing.", "panel:Inspector"),
            S("Try both approaches", "Check, Build and Play. Approach from both sides, follow the leaf to its open position, and wait for it to close. Confirm its moving collision frees the whole route. For two sliding leaves, use the separate Double sliding doors tutorial.", "action:build.check")]),
        new("door-rising", "Build a rising security door", "door raise raised roller shutter vertical overhead travel industrial security", [
            S("Find the rising preset", "Raised security door is selected in Prefabs. It supplies a framed leaf that moves upward on contact. This preset fits an existing opening. To cut a new opening instead, choose Security and Movement Raise in Doors, then use Place Door.", "prefab:roller_door"),
            S("Size before placing", "Set Width, Height and Move time in the preset, then drag its tile to the floor at the centre of the opening. Reserve space above the lintel for the entire raised leaf. Escape cancels an unfinished placement.", "prefab:roller_door|Height"),
            S("Inspect the raised pose", "Select the placed leaf and open Inspector. Movement Raise moves vertically; Travel 0 clears its height and frame. Show open previews the overhead position. Keep Reverse opening off for upward travel and end the preview with Show closed.", "panel:Inspector"),
            S("Choose its interaction", "Set Activation to Contact · timed for a door opened by approaching it. Open time controls travel speed and Stay open controls the timed pause. Trigger modes need a linked switch, sensor or hack panel; their tutorials explain those assemblies.", "panel:Inspector"),
            S("Check overhead clearance", "Check, Build and Play. Walk under the fully raised door from both sides and wait for it to close. Inspect the ceiling, upper floor and collision along its whole vertical path; a clear closed doorway alone does not prove the raised position fits.", "action:build.check")]),
        new("door-double-hinged", "Build double hinged doors", "door double hinged pair swing leaves shared frame no centre post", [
            S("Choose the hinged pair", "Double hinged doors is selected in Prefabs. It contains two leaves, one shared frame without a centre post and separately configured side sensors. Its default automatic access allows both teams from both sides.", "prefab:double_hinged_door"),
            S("Set the pair's dimensions", "Width is the total clear doorway width; each leaf uses half. Set Height, Style, Angle and Move time before placing. Keep Movement hinged. Leave room for both leaves to swing and keep the centre of the doorway clear.", "prefab:double_hinged_door|Width"),
            S("Choose access and place", "Set Front access and Back access independently to spies, mercs, both or none. Drag the tile to the floor at the doorway centre; its wall runs along Y before rotation. Rotate the whole assembly to match the wall. Opening carves a doorway; turn it off for an existing opening.", "prefab:double_hinged_door|Front access"),
            S("Edit the whole assembly", "Select a placed part. In Prefabs use Apply to selected to rebuild that pair from its shared parameters. This replaces individual hand edits. Move or rotate all parts together when repositioning the doorway. Painting either leaf applies its material to both leaves.", "panel:Prefabs"),
            S("Test paired opening", "Check, Build and Play with both teams from both sides. Both leaves should open together and stay open while an eligible player occupies a side sensor, then close after the last eligible player leaves. Check each swing and the unobstructed centre gap.", "action:build.check")]),
        new("door-double-sliding", "Build double sliding doors", "door double sliding split pair leaves shared frame no centre post", [
            S("Choose the sliding pair", "Double sliding doors is selected in Prefabs. Its two leaves slide apart from the middle, with one shared frame and no centre post. The default side sensors allow both teams and keep both leaves open together.", "prefab:double_sliding_door"),
            S("Reserve both side pockets", "Width is the total clear opening, divided between the two leaves. Set Height, Style and Move time, keeping Movement sliding. Leave enough free space beside both jambs for a half-width leaf to slide out of the route.", "prefab:double_sliding_door|Width"),
            S("Set access and position", "Set Front access and Back access separately. Drag the tile to floor level at the doorway centre, then rotate the whole assembly to face the wall. Opening cuts through editable walls to Depth; disable it when the doorway already exists.", "prefab:double_sliding_door|Back access"),
            S("Customise the placed pair", "Select any part and use the prefab's Apply to selected for shared settings; rebuilding replaces hand edits to individual parts. Drag a material onto either leaf to paint both. Enable Hack panel only when you also want the linked hacking interaction.", "panel:Prefabs"),
            S("Test both leaves and sensors", "Check, Build and Play. Confirm both leaves separate fully and close together. Test each team's approach from each side and leave one eligible player in a sensor while another leaves: the pair should remain open until the last eligible occupant leaves.", "action:build.check")]),
        new("door-activation", "Choose door activation and timing", "door interaction contact bump timed trigger toggle held control once switch sensor open close", [
            S("Select the door to configure", "Select an editable door and find its Door section in Inspector. Activation controls what opens it; Movement controls where it goes. Set Open time for travel duration. Stay open is the pause used by timed activation, not the travel time.", "panel:Inspector"),
            S("Open on contact", "Contact · timed opens when a player bumps the door and closes after Stay open seconds. It needs no switch. For different team permissions on each side, use an Automatic access assembly and its dedicated tutorial instead.", "panel:Inspector"),
            S("Use toggle or timed events", "Trigger · toggle alternates open and closed on successive events. Trigger · timed opens on an event and closes after Stay open. Door with a switch is selected here as a ready-linked example; its State parameter offers TriggerToggle and TriggerOpenTimed.", "prefab:door_switch|State"),
            S("Hold open or open once", "Trigger · held stays open between a linked trigger's activation and release, so use a sensor or other source that sends both. Trigger · once opens permanently after its first event. Set these in the placed door's Inspector. Automatic access and Hack panel presets supply suitable interactions.", "panel:Inspector"),
            S("Keep the event connection", "A trigger mode alone does not connect a switch. The source's Event must match the door's Tag; a prefab supplies that link and keeps each copy independent. Use the Door with a switch, Automatic access or Hack panel tutorial for placement and wiring guidance.", "panel:Connections"),
            S("Test the chosen state", "Check, Build and Play. Try repeated uses, leave and re-enter sensors, and watch the whole close cycle. For once-only opening, start a fresh round to test the initial locked state again. Verify one placed copy never opens an unrelated copy.", "action:build.check")]),
        new("door-hacking", "Build a hackable door and move its panel", "door hacking hack panel time duration seconds timed permanent move linked link interrupteur double", [
            S("Start with a hackable assembly", "Hackable access door is selected in Prefabs. It starts with Hack panel enabled and both automatic sides set to none, so opening requires a successful hack. The panel model needs shared gameplay content. Double-door presets can enable the same Hack panel option.", "prefab:hackable_door"),
            S("Set hack duration and result", "Set Hack time to the required uninterrupted seconds. Hack state TriggerOpenTimed opens for Stay open seconds; TriggerOpenOnceOnly keeps the door open after the first successful hack. Set both Front access and Back access to none for a hack-only door.", "prefab:hackable_door|Hack time"),
            S("Place a reachable panel", "Choose the initial Panel side, Panel height and Panel offset, then place the whole assembly at the doorway's floor centre. Leave a reachable approach to the panel and enough space for the moving leaf. Rotate all parts together when orienting the doorway.", "prefab:hackable_door|Panel height"),
            S("Move the linked panel", "Select only the placed hack panel and move or rotate it with the normal tools. Its Event continues to target the same door or pair; moving it does not require relinking. Do not use Apply to selected merely to move it: rebuilding restores its initial prefab position.", "action:tools.move"),
            S("Tune the placed panel", "With the panel selected, Inspector's Door hack panel section offers Hack time and Select linked doors. Change the duration there to keep its current position and event link. Select linked doors lets you verify the connection and inspect the target leaves.", "panel:Inspector|Door hack panel"),
            S("Test success and cancellation", "Check, Build and Play as a spy. Start a hack and cancel before completion: the door should remain shut. Complete the configured duration and verify timed closing or permanent opening. Test another copy for event isolation, and start a fresh round to check its initial state.", "action:build.check")]),
        new("door-automatic", "Build doors with automatic team access", "door automatic proximity sensor spies spy mercs mercenary both neither front back side access asymmetric one way", [
            S("Choose an automatic assembly", "Automatic access door is selected in Prefabs. It contains a door and a separate sensor on each side. Double hinged doors and Double sliding doors offer the same access parameters and open both leaves together.", "prefab:automatic_door"),
            S("Configure the front", "Front access controls the +X side before the assembly is rotated. Choose spies, mercs, both or none. For example, set spies here to let only spies activate this side automatically. The rule controls activation; an already open doorway can still be crossed.", "prefab:automatic_door|Front access"),
            S("Configure the back independently", "Back access controls the opposite, -X side and has the same four choices. For a different rule on each side, try front spies and back mercs. Both allows either team; none disables that side's automatic opening. Rotate the whole assembly so these sides face the intended rooms.", "prefab:automatic_door|Back access"),
            S("Choose the detection space", "Approach sets the depth of each side's detection volume beyond the wall. Place the assembly with sensors in accessible space on their own sides, clear of nearby routes that should not activate this door. The two sensor volumes stay apart through the doorway.", "prefab:automatic_door|Approach"),
            S("Combine automatic access with hacking", "Leave Hack panel off for occupancy-controlled opening: an eligible occupant holds it open until the last one leaves. With Hack panel enabled, allowed teams can still use their automatic side without hacking; the panel gives a timed or permanent opening according to Hack state. Both sides none requires hacking.", "prefab:automatic_door|Hack panel"),
            S("Test all four approaches", "Check, Build and Play as a spy and a mercenary from both sides. Confirm the correct team activates each side, then test two eligible players entering and leaving the sensors. Check that the door stays open until the last eligible occupant leaves and that adjacent doors remain independent.", "action:build.check")]),
        new("door-materials", "Paint door leaves and frames", "door material texture drag drop finish paint skin double pair frame jamb resize save", [
            S("Select a door to paint", "Place a door or open a map with editable doors. Use Show closed in the selected door's Inspector so its leaf and frame are easy to target. A standalone door stores separate Door material and Frame material finishes.", "panel:Inspector"),
            S("Drag onto the leaf", "In Assets choose Materials and find a finish. Drag the material tile directly onto the visible door leaf. A prefab pair receives the finish on both leaves together. Dropping on nearby geometry paints that geometry instead, so check the highlighted target before releasing.", "assetkind:Material"),
            S("Paint the frame separately", "Drag another material onto a standalone door's jamb or lintel to change its frame finish. A double-door assembly's shared frame is brush geometry and can be painted with Surface. Painting leaves and frames preserves the door's movement, timing and event links.", "assetkind:Material"),
            S("Check editing and persistence", "Undo and Redo the paint, then resize the door to confirm the finish stays. Save, reopen and Build the project to check the result. Applying prefab parameters rebuilds an instance from those settings, so also set its Material or Frame material parameter if you plan to rebuild it later.", "action:file.save")]),
    ];
}
